#include "backlogsummary.h"
#include "issuemodel.h"

#include <QAbstractItemModel>

BacklogSummary::BacklogSummary(IssueModel *model, QObject *parent)
    : QObject(parent), m_model(model)
{
    if (m_model) {
        connect(m_model, &QAbstractItemModel::rowsInserted, this, &BacklogSummary::onRowsInserted);
        connect(m_model, &QAbstractItemModel::rowsRemoved, this, &BacklogSummary::onRowsRemoved);
        connect(m_model, &QAbstractItemModel::modelReset, this, &BacklogSummary::onModelReset);
        connect(m_model, &QAbstractItemModel::dataChanged, this, &BacklogSummary::onDataChanged);
        updateTotal();
    }
}

int BacklogSummary::openMinutes() const
{
    return m_openMinutes;
}

void BacklogSummary::updateTotal()
{
    int total = 0;
    if (m_model) {
        for (int i = 0; i < m_model->rowCount(); ++i) {
            const QModelIndex idx = m_model->index(i, 0);
            const bool closed = m_model->data(idx, IssueModel::ClosedRole).toBool();
            const int est = m_model->data(idx, IssueModel::EstimateRole).toInt();
            if (!closed)
                total += est;
        }
    }
    if (total != m_openMinutes) {
        m_openMinutes = total;
        emit totalChanged(m_openMinutes);
    }
}

void BacklogSummary::onRowsInserted(const QModelIndex &parent, int start, int end)
{
    Q_UNUSED(parent)
    Q_UNUSED(end)
    updateTotal();
}

void BacklogSummary::onRowsRemoved(const QModelIndex &parent, int start, int end)
{
    Q_UNUSED(parent)
    Q_UNUSED(end)
    updateTotal();
}

void BacklogSummary::onModelReset()
{
    updateTotal();
}

void BacklogSummary::onDataChanged(const QModelIndex &topLeft, const QModelIndex &bottomRight)
{
    Q_UNUSED(topLeft)
    Q_UNUSED(bottomRight)
    updateTotal();
