#include <QAbstractItemModel>
#include <QPointer>

class BacklogSummaryPrivate
{
public:
    explicit BacklogSummaryPrivate(BacklogSummary *qq) : q(qq) {}

    QPointer<IssueModel> model;
    int m_openMinutes = 0;
    BacklogSummary *q;

    void recalculate()
    {
        int total = 0;
        if (model) {
            for (int i = 0; i < model->rowCount(); ++i) {
                const QModelIndex idx = model->index(i, 0);
                const bool closed = model->data(idx, IssueModel::ClosedRole).toBool();
                const int est = model->data(idx, IssueModel::EstimateRole).toInt();
                if (!closed)
                    total += est;
            }
        }
        if (total != m_openMinutes) {
            m_openMinutes = total;
            emit q->totalChanged(m_openMinutes);
        }
    }

    void onModelDestroyed()
    {
        if (m_openMinutes != 0) {
            m_openMinutes = 0;
            emit q->totalChanged(0);
        }
        model = nullptr;
    }
};

BacklogSummary::BacklogSummary(IssueModel *model, QObject *parent)
    : QObject(parent), d_ptr(new BacklogSummaryPrivate(this))
{
    if (model) {
        d_ptr->model = model;
        connect(model, &QAbstractItemModel::rowsInserted,
                d_ptr.get(), &BacklogSummaryPrivate::recalculate);
        connect(model, &QAbstractItemModel::rowsRemoved,
                d_ptr.get(), &BacklogSummaryPrivate::recalculate);
        connect(model, &QAbstractItemModel::modelReset,
                d_ptr.get(), &BacklogSummaryPrivate::recalculate);
        connect(model, &QAbstractItemModel::dataChanged,
                d_ptr.get(), &BacklogSummaryPrivate::recalculate);
        connect(model, &QObject::destroyed,
                d_ptr.get(), &BacklogSummaryPrivate::onModelDestroyed);
        d_ptr->recalculate();
    }
}

int BacklogSummary::openMinutes() const
{
    return d_ptr ? d_ptr->m_openMinutes : 0;
}

